style.css:
@-moz-document domain("youtube.com") {
/* Container adjustments */
#related #dismissible {
    position: relative !important;
    padding-right: 60px !important; /* Reduced from 100px to give more text space */
    min-height: 60px !important; /* Match thumbnail height */
}

/* Thumbnail positioning (keep your working right-aligned version) */
#related ytd-thumbnail {
    position: absolute !important;
    right: 0 !important;
    top: 0 !important;
    width: 80px !important; /* Slightly smaller */
    height: 50px !important; /* Slightly smaller */
    margin: 0 !important;
}

/* Text container expansion */
#related .details {
    width: 100% !important; /* Take all available space */
    max-width: none !important;
    padding-right: 0 !important;
}

/* Bigger text area */
#related .metadata {
    width: 100% !important;
}

/* Larger text */
#related #video-title {
    -webkit-line-clamp: 3 !important;
    display: -webkit-box !important;
    -webkit-box-orient: vertical !important;
    overflow: hidden !important;
    margin-bottom: 4px !important;
}

/* Channel name and metadata */
#related ytd-channel-name, 
.inline-metadata-item {
    white-space: nowrap !important;
}

/* Progress bar fix */
#related ytd-thumbnail-overlay-resume-playback-renderer {
    width: calc(100% - 80px) !important;
    left: 0 !important;
}

/* Add border between video items */
#related ytd-compact-video-renderer {
    border-bottom: 1px solid rgba(255, 255, 255, 0.1) !important; /* Light line for dark mode */
    padding-bottom: 8px !important;
    margin-bottom: 8px !important;
}

/* For YouTube light mode */
#related html:not(.dark) ytd-compact-video-renderer {
    border-bottom-color: rgba(0, 0, 0, 0.1) !important; /* Darker line for light mode */
}

/* Adjust last item to not have extra space */
#related ytd-compact-video-renderer:last-child {
    border-bottom: none !important;
    margin-bottom: 0 !important;
    padding-bottom: 0 !important;
  }
}
